// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getVisit } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

// Local, not shared: this POST body deliberately OMITS durationMinutes, which the
// shared createVisit helper always sends. Structurally different, so it stays here.
async function createVisitWithoutDuration(client, url, date, description, petId, expectedStatus = 201) {
    const visitsPostRequestBody: string = `{
        "date": "${date}",
        "description": "${description}",
        "petId": ${petId}
    }`;

    const visitsPostResponse = await client.sendRequest({
        url: url,
        path: "/petclinic/api/visits",
        method: "POST",
        body: visitsPostRequestBody
    });

    expect(visitsPostResponse.statusCode, 'status code').toBe(expectedStatus);
    return visitsPostResponse;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    const visitsPostResponse = await createVisitWithoutDuration(client, URL_localhost, "2026-08-04", "no duration supplied", 7);
    expect(getResponseValue(visitsPostResponse, "id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(visitsPostResponse, "date"), 'date').toBe("2026-08-04");
    expect(getResponseValue(visitsPostResponse, "description"), 'description').toBe("no duration supplied");
    expect(getResponseValue(visitsPostResponse, "petId"), 'petId').toBe(7);
    // openapi.yml declares `default: 30` for VisitFields.durationMinutes, so an omitted
    // duration is materialised as 30 rather than left null.
    expect(getResponseValue(visitsPostResponse, "durationMinutes"), 'durationMinutes').toBe(30);

    const visitsVisitsGetResponse = await getVisit(client, URL_localhost, getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "id"), 'id').toBe(getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "date"), 'date').toBe("2026-08-04");
    expect(getResponseValue(visitsVisitsGetResponse, "description"), 'description').toBe("no duration supplied");
    expect(getResponseValue(visitsVisitsGetResponse, "petId"), 'petId').toBe(7);
    expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'durationMinutes').toBe(30);
});
